16	#include "sandstone.h"
17	#include <cstdint>
18	#include <cstring>
19	
20	#define AGU_STRESS_2SRC_COUNT 1024
21	
22	struct AguStress2srcData {
23	    uint64_t *srcA;
24	    uint64_t *srcB;
25	    uint64_t *expected;
26	};
27	
28	#if defined(__x86_64__) || defined(__i386__)
29	
30	static inline void store_qword(void *addr, uint64_t val) {
31	    __asm__ volatile ("movq %1, %0" : "=m"(*reinterpret_cast<uint64_t*>(addr)) : "r"(val) : "memory");
32	}
33	
34	static inline uint64_t load_qword(const void *addr) {
35	    uint64_t res;
36	    __asm__ volatile ("movq %1, %0" : "=r"(res) : "m"(*reinterpret_cast<const uint64_t*>(addr)) : "memory");
37	    return res;
38	}
39	
40	#elif defined(__aarch64__)
41	
42	static inline void store_qword(void *addr, uint64_t val) {
43	    __asm__ volatile ("str %1, [%0]" : : "r"(addr), "r"(val) : "memory");
44	}
45	
46	static inline uint64_t load_qword(const void *addr) {
47	    uint64_t res;
48	    __asm__ volatile ("ldr %0, [%1]" : "=r"(res) : "r"(addr) : "memory");
49	    return res;
50	}
51	
52	#endif
