54	static int agu_stress_2src_init(struct test *test) {
55	    auto *data = static_cast<AguStress2srcData *>(malloc(sizeof(AguStress2srcData)));
56	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)));
57	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)));
58	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)));
59	
60	    memset_random(data->srcA, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t));
61	    memset_random(data->srcB, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t));
62	
63	    for (int i = 0; i < AGU_STRESS_2SRC_COUNT; i++) {
64	        switch (i % 4) {
65	            case 0: data->expected[i] = data->srcA[i] + data->srcB[i]; break;
66	            case 1: data->expected[i] = data->srcA[i] ^ data->srcB[i]; break;
67	            case 2: data->expected[i] = data->srcA[i] & data->srcB[i]; break;
68	            case 3: data->expected[i] = data->srcA[i] | data->srcB[i]; break;
69	        }
70	    }
71	
72	    test->data = data;
73	    return EXIT_SUCCESS;
74	}
75	
76	static int agu_stress_2src_run(struct test *test, int cpu) {
77	    auto *data = static_cast<AguStress2srcData *>(test->data);
78	
79	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)));
80	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)));
81	
82	    TEST_LOOP(test, 1 << 13) {
83	        for (int i = 0; i < AGU_STRESS_2SRC_COUNT; i++) {
84	            uint64_t a = data->srcA[i];
85	            uint64_t b = data->srcB[i];
86	            uint64_t res;
87	
88	            switch (i % 4) {
89	                case 0: res = a + b; break;
90	                case 1: res = a ^ b; break;
91	                case 2: res = a & b; break;
92	                case 3: res = a | b; break;
93	            }
94	
95	            store_qword(&temp[i], res);
96	            store_qword(&dst[i], load_qword(&temp[i]));
97	        }
98	
99	        if (memcmp(dst, data->expected, AGU_STRESS_2SRC_COUNT * sizeof(uint64_t)) != 0) {
100	            report_fail_msg("agu_stress_2src data miscompare");
101	        }
102	    }
103	
104	    free(dst);
105	    free(temp);
106	    return EXIT_SUCCESS;
107	}
108	
109	static int agu_stress_2src_cleanup(struct test *test) {
110	    auto *data = static_cast<AguStress2srcData *>(test->data);
111	    if (data) {
112	        free(data->srcA);
113	        free(data->srcB);
114	        free(data->expected);
115	        free(data);
116	    }
117	    return EXIT_SUCCESS;
118	}
119	
120	DECLARE_TEST(agu_stress_2src, "AGU stress: 2-source load + rotating ALU {add,eor,and,orr} + store/reload/store")
121	    .test_init    = agu_stress_2src_init,
122	    .test_run     = agu_stress_2src_run,
123	    .test_cleanup = agu_stress_2src_cleanup,
124	    .quality_level = TEST_QUALITY_PROD,
125	END_DECLARE_TEST
